 * Opening numbers the claim and records who opened it; a voided claim keeps its number, which
 * is never reused. The user who opened a claim,
 * or last edited it, is refused when settling it. A clerk settling a claim whose due is above the sheet's clerk limit
 * (a due of n/a is within any limit) sends it PENDING instead, for a steward to approve or reject;
 * a steward settles any. A move the sheet's permission matrix does not allow the user's role is
 * refused. A claim due by inside a closed period cannot be moved, nor can a claim
 * deferred on the sheet's today be settled, nor a claim opened whose person already has as many OPEN
 * or PENDING claims due by in its period as the period's claim cap. A claim opened whose due is above the
 * sheet's review threshold in force on its date (a due of n/a is within any threshold) goes to REVIEW
 * instead, with no number yet, audited as CLAIM_REVIEW (see {@link #review}). A SETTLED claim is voided only by a steward, within
 * {@link ClaimStatus#VOID_SETTLED_DAYS} days of its settlement; its frozen figure leaves every
 * total and the audit records it as reversed.
 */
@Transactional
public Claim move(String sheetId, String user, long claimId, ClaimStatus next) {
    return move(sheetId, user, claimId, next, null);
}

/**
 * Move a claim as {@link #move(String, String, long, ClaimStatus)} does, voiding it with a reason:
 * while the sheet's list of void reasons is not empty, a void needs one from it (see
 * {@link VoidReasonService#require}); the claim keeps it and its audit record ends with it.
 */
@Transactional
public Claim move(String sheetId, String user, long claimId, ClaimStatus next, String reason) {
    // Every move takes the sheet's lock before reading the claim, so concurrent opens on the
    // sheet are serialised: each sees the other's committed claim and number.
    LocalDate today = sheets.lock(sheetId).getToday();
    Rollups.Rollup before = rollups.take(sheetId);
    Claim claim = claim(sheetId, claimId);
    periods.refuseIfClosed(sheetId, claim.getDueBy());
    String action = switch (next) {
        case OPEN -> "open";
        case SETTLED -> "settle";
        case VOID -> "void";
        case PENDING, DRAFT, DELETED, REVIEW -> throw new IllegalArgumentException("No move to " + next + ".");
    };
    if (!roles.permits(sheetId, user, action)) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " a claim.");
    }
    if (!claim.getStatus().canBecome(next)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "A " + claim.getStatus() + " claim cannot become " + next + ".");
    }
    boolean voidingSettled = next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED;
    if (voidingSettled) {
        refuseVoidingSettled(sheetId, user, claim, today);
    }
    String voidReason = next == ClaimStatus.VOID ? voidReasons.require(sheetId, reason) : null;
    if (next == ClaimStatus.SETTLED && claim.isDeferredOn(today)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "The claim is deferred until " + claim.getDeferredUntil() + ": it cannot be settled before then.");
    }
    if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                "The user who opened or last edited a claim cannot settle it.");
    }
    Person person = person(sheetId, claim.getPersonId());
    BigDecimal settledDue = next == ClaimStatus.SETTLED
            ? dues.settling(claim, person.gradeOn(claim.getDate()))
            : null;
    if (next == ClaimStatus.OPEN) {
        periods.refuseIfCapped(sheetId, claim);
        BigDecimal due = dues.due(claim, person.gradeOn(claim.getDate()));
        refuseUnnoted(sheetId, claim, due);
        if (overReviewThreshold(sheetId, claim, due)) {
            next = ClaimStatus.REVIEW;
        }
    }
    if (next == ClaimStatus.SETTLED) {
        refuseUnproved(sheetId, claim, person.gradeOn(claim.getDate()), settledDue);
    }
    if (next == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, settledDue)) {
        next = ClaimStatus.PENDING;
        settledDue = null;
    }
    claim.become(next);
    if (next == ClaimStatus.OPEN) {
        claim.number(periods.nextClaimNumber(sheetId, claim.getDueBy()));
    }
    if (next == ClaimStatus.OPEN || next == ClaimStatus.REVIEW) {
        claim.openedBy(user);
    }
    if (next == ClaimStatus.SETTLED) {
        claim.settleDue(settledDue);
    }
    if (next == ClaimStatus.VOID) {
        claim.voidedWith(voidReason);
    }
    Claim saved = logged(claims.saveAndFlush(claim), user, person);
    String event = switch (next) {
        case OPEN -> "CLAIM_OPENED";
        case SETTLED -> "CLAIM_SETTLED";
        case PENDING -> "CLAIM_PENDING";
        case REVIEW -> "CLAIM_REVIEW";
        case VOID -> "CLAIM_VOIDED";
        case DRAFT, DELETED -> throw new IllegalStateException();
    };
    String suffix = next == ClaimStatus.SETTLED
 * What the screen is told about a claim; the amount with two decimals, and the due fixed when it
 * was settled (null when not fixed, so its due is worked out from the current rate), and who
 * opened it (null until opened), and whether it is bound by its person's last statement, with the
 * figure it was bound to (null when unbound, or when it was n/a), and the number of the claim it
 * corrects (null unless it is a correction), and the date it is due by, fixed when it was added, and its status
 * log, oldest first, and the date it is deferred until (null when it was never deferred), and its proofs count,
 * and the number of the claim it was split from (null unless it was split off another), and the user whose open
 * editor locks it (null when none does), and the last day it was reminded (null when never), and its
 * external reference (null when it has none), and its tags, sorted, and every tag it has ever carried, sorted,
 * and the reason it was voided with (null when none), and its comments, oldest first, and the user who last edited it (null when never), and the number of the bulk settle batch that settled
 * it (null when none did), and its lines, in the order they were added.
 */
public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note, ClaimStatus status,
        String number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects, List<LogLineView> log,
        LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy, boolean lateEntry, LocalDate remindedOn,
        String ref, List<String> tags, List<String> tagsUsed, String voidReason, List<CommentView> comments,
        String editedBy, Integer settleBatch, List<LineView> lines, Long added) {

    public static ClaimView of(Claim claim) {
        return new ClaimView(claim.getId(), claim.getPersonId(), claim.getAmount().toPlainString(),
                claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                claim.getSettledDue() == null ? null : claim.getSettledDue().toPlainString(),
                claim.getOpenedBy(), claim.isStated(),
                claim.getStatedDue() == null ? null : claim.getStatedDue().toPlainString(),
                claim.getCorrects(), claim.getLog().stream().map(LogLineView::of).toList(), claim.getDeferredUntil(),
                claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(), claim.isLateEntry(), claim.getRemindedOn(),
                claim.getRef(), claim.getTags(), claim.getTagsUsed(), claim.getVoidReason(),
                claim.getComments().stream().map(CommentView::of).toList(), claim.getEditedBy(),
                claim.getSettleBatch(), claim.getLines().stream().map(LineView::of).toList(), claim.getAdded());
    }
}

/** A line of a claim's status log; the due with two decimals, or n/a. */
public record LogLineView(ClaimStatus status, String by, LocalDate on, String due) {

    public static LogLineView of(ClaimLogLine line) {
        return new LogLineView(line.getStatus(), line.getBy(), line.getOn(),
                line.getDue() == null ? "n/a" : line.getDue().toPlainString());
    }
}

/** A comment on a claim: by whom, on the sheet's today then, and its text. */
public record CommentView(String by, LocalDate on, String text) {

    public static CommentView of(ClaimComment comment) {
        return new CommentView(comment.getBy(), comment.getOn(), comment.getText());
    }
}

/** A line of a claim: its label, quantity and unit amount with two decimals. */
public record LineView(String label, int qty, String unit) {
/** The date the claim is deferred until; null when it was never deferred. */
@Column(name = "deferred_until")
private LocalDate deferredUntil;

/** The number of the claim this one was split from; null unless it was split off another. */
@Column(name = "split_from")
private String splitFrom;

/** How many proofs the claim has; 0 when added. */
@Column(name = "proofs", nullable = false)
private int proofs;

/** The last day (the sheet's today) a reminder was written for the claim; null when never reminded. */
@Column(name = "reminded_on")
private LocalDate remindedOn;

/** Whether a reminder ever escalated the claim; a claim escalates once at most. */
@Column(name = "escalated", nullable = false)
private boolean escalated;

/** The user whose open editor locks the claim for everyone else; null when no editor holds it. */
}

/** Raise the claim's proofs count by one; the caller checks the claim can take a proof. */
public void addProof() {
    proofs++;
}

public LocalDate getRemindedOn() {
    return remindedOn;
}

/** Mark the claim reminded on a day; the caller checks the claim can be reminded. */
public void remind(LocalDate on) {
    this.remindedOn = on;
}

public boolean isEscalated() {
    return escalated;
}

/** Mark the claim escalated; the caller checks it was not already. */
public void escalate() {
    this.escalated = true;
}

