  expect(await ui.setSettingDated(pg_uma, "late-pct", "5.00", "2026-03-01", "5.00")).toBe(true);
  expect(await ui.addAlias(pg_uma, p_cam, "")).toBe(false);
  expect(await ui.importPeople(pg_uma, "Eve,C\nFay,C,,")).toMatchObject({"added": 2, "updated": 0});
  const p_eve = await ui.personId(pg_uma, "Eve");
  const p_fay = await ui.personId(pg_uma, "Fay");
  expect(await ui.hold(pg_uma, p_eve, {"from": "2026-02-10", "to": "2026-03-05"})).toBe(true);
  expect(await ui.addPatron(pg_uma, p_cam, "Fay")).toBe(true);
  expect(await ui.statement(pg_uma, p_eve)).toBe(true);
  expect(await ui.bulkGrade(pg_uma, [p_cam, p_eve], {"grade": "A"})).toBe(2);
